import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

const dbPath = process.env.DB_PATH || './workboard.sqlite';
if (dbPath !== ':memory:') mkdirSync(dirname(dbPath), { recursive: true });
const db = new DatabaseSync(dbPath);
db.exec(`CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, archived INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS tasks (id INTEGER PRIMARY KEY AUTOINCREMENT, project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE, title TEXT NOT NULL, completed INTEGER NOT NULL DEFAULT 0)`);
// Upgrade databases created by earlier task checkpoints.
if (!db.prepare('PRAGMA table_info(projects)').all().some(c => c.name === 'archived')) db.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0');

const page = `<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Workboard</title>
<style>body{font:16px system-ui,sans-serif;max-width:760px;margin:3rem auto;padding:0 1rem;color:#172033}h1{font-size:2rem}form{display:flex;gap:.6rem;margin:1.5rem 0}input,button,select{font:inherit;padding:.55rem .8rem}input{flex:1;border:1px solid #9aa4b2;border-radius:4px}button{cursor:pointer;border:0;border-radius:4px;background:#2459a9;color:white}.project-row{display:flex;align-items:center;gap:1rem;padding:.8rem;border-bottom:1px solid #ddd}.project-name{flex:1}.alert{color:#a31621;margin:.5rem 0}</style></head>
<body><main id="app"></main><script>
const app=document.getElementById('app');
async function projects(){return (await fetch('/api/projects')).json()}
function go(path){history.pushState({},'',path);render()}
async function render(){const match=location.pathname.match(/^\\/projects\\/(\\d+)\\/?$/);if(match){const items=await projects();const p=items.find(x=>String(x.id)===match[1]);if(!p){go('/');return}
app.innerHTML='<button id="back">Projects</button><h1></h1><form id="rename-form"><label for="new-project-name">New project name</label><input id="new-project-name"><button type="submit">Rename project</button></form><p id="archived"></p><form id="task-form"><label for="task-title">Task title</label><input id="task-title"><button type="submit">Create task</button></form><div id="alert" class="alert" role="alert"></div><label for="task-filter">Task filter</label><select id="task-filter"><option>All</option><option>Open</option><option>Completed</option></select><section id="tasks"></section>';
app.querySelector('h1').textContent=p.name;app.querySelector('#back').onclick=()=>go('/');const renameInput=app.querySelector('#new-project-name'),renameButton=app.querySelector('#rename-form button');renameInput.disabled=!!p.archived;renameButton.disabled=!!p.archived;app.querySelector('#rename-form').onsubmit=async e=>{e.preventDefault();const name=renameInput.value.trim();if(!name){app.querySelector('#alert').textContent='Project name is required';return}await fetch('/api/projects/'+p.id,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({name})});render()};if(p.archived){app.querySelector('#archived').textContent='Archived project';app.querySelector('#task-title').disabled=true;app.querySelector('#task-form button').disabled=true}
const filter=app.querySelector('#task-filter');const load=async()=>{const tasks=await(await fetch('/api/projects/'+p.id+'/tasks')).json();const section=app.querySelector('#tasks');section.replaceChildren();for(const t of tasks){if(filter.value==='Open'&&t.completed||filter.value==='Completed'&&!t.completed)continue;const row=document.createElement('div');row.dataset.testid='task-row';row.className='project-row';const title=document.createElement('span');title.textContent=t.title;const checkbox=document.createElement('input');checkbox.type='checkbox';checkbox.checked=!!t.completed;checkbox.disabled=!!p.archived;checkbox.setAttribute('aria-label','Complete '+t.title);checkbox.onchange=async()=>{await fetch('/api/tasks/'+t.id,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({completed:checkbox.checked})});load()};row.append(title,checkbox);section.append(row)}};
filter.onchange=load;app.querySelector('#task-form').onsubmit=async e=>{e.preventDefault();const input=app.querySelector('#task-title'),title=input.value.trim();if(!title){app.querySelector('#alert').textContent='Task title is required';return}await fetch('/api/projects/'+p.id+'/tasks',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({title})});input.value='';app.querySelector('#alert').textContent='';load()};load();return}
app.innerHTML='<h1>Workboard</h1><form id="project-form"><label for="project-name">Project name</label><input id="project-name"><button type="submit">Create project</button></form><div id="alert" class="alert" role="alert"></div><label for="project-filter">Project filter</label><select id="project-filter"><option>Active</option><option>Archived</option></select><section id="projects"></section>';
const form=app.querySelector('#project-form');form.onsubmit=async e=>{e.preventDefault();const input=app.querySelector('#project-name'),name=input.value.trim();if(!name){app.querySelector('#alert').textContent='Project name is required';return}await fetch('/api/projects',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({name})});render()};
const filter=app.querySelector('#project-filter');const draw=async()=>{const list=await projects(),section=app.querySelector('#projects');section.replaceChildren();for(const p of list){if(filter.value==='Active'&&p.archived||filter.value==='Archived'&&!p.archived)continue;const row=document.createElement('div');row.dataset.testid='project-row';row.className='project-row';const name=document.createElement('span');name.className='project-name';name.textContent=p.name;const summary=document.createElement('span');summary.dataset.testid='project-summary';summary.textContent=p.completedCount+'/'+p.totalCount+' completed';const open=document.createElement('button');open.textContent='Open project';open.onclick=()=>go('/projects/'+p.id);const action=document.createElement('button');action.textContent=p.archived?'Restore project':'Archive project';action.onclick=async()=>{await fetch('/api/projects/'+p.id,{method:'PATCH',headers:{'content-type':'application/json'},body:JSON.stringify({archived:!p.archived})});draw()};row.append(name,summary,open,action);section.append(row)}};filter.onchange=draw;draw()
}
